local AssetService = game:GetService("AssetService")
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")

local function ext(path: string): Instance?
	local cur: Instance? = game
	for _, name in string.split(path, ".") do
		cur = cur and (cur:FindFirstChild(name) or (cur == game and game:FindService(name)) or nil)
		if not cur then return nil end
	end
	return cur
end

local function applyProps(inst: Instance, props: {[string]: any})
	for k, v in props do
		if k == "Tags" then
			for _, t in v do CollectionService:AddTag(inst, t) end
		elseif k == "Attributes" then
			for an, av in v do inst:SetAttribute(an, av) end
		else
			inst[k] = v
		end
	end
end

local function setup(inst: Instance, parent: Instance?, props: {[string]: any})
	if not pcall(applyProps, inst, props) then
		for k, v in props do
			pcall(applyProps, inst, {[k] = v})
		end
	end
	inst.Parent = parent
	return inst
end

local function new(className: string, parent: Instance?, props: {[string]: any})
	return setup(Instance.new(className), parent, props)
end

local function meshPart(parent: Instance?, meshId: string, options: {[string]: any}, props: {[string]: any})
	local ok, part = pcall(AssetService.CreateMeshPartAsync, AssetService, meshId, options)
	if not ok then
		part = Instance.new("Part")
	end
	return setup(part, parent, props)
end

